import {
  HistogramThresholdData,
  TimeseriesThresholdData,
} from '../types/thresholds.js';
import { isStatic, isDynamicNumeric, isDynamic } from '../types/type-guards.js';

const isDot = (threshold: TimeseriesThresholdData | HistogramThresholdData) =>
  isStatic(threshold) || isDynamic(threshold) || isDynamicNumeric(threshold);

export const sortThresolds = (
  threshold1: TimeseriesThresholdData | HistogramThresholdData,
  threshold2: TimeseriesThresholdData | HistogramThresholdData,
): number => +isDot(threshold1) - +isDot(threshold2);
